1	import { and, asc, desc, eq, inArray } from "drizzle-orm";
2	import { schema, type DB } from "../db";
3	import { newId, now } from "../ids";
4	import { chatFull } from "../ai";
5	import { asLang, fmtDate, fmtEta, fmtHours, T, type Lang } from "./i18n";
6	import { closeDelta, parseSimplePlan, plansEqual, shiftClose, validatePlan } from "./plan";
7	import type { DayPlan } from "./types";
8	import type { Reason } from "./reasons";
9	import { renderAll, type Bundle, type Item } from "./messages";
10	import type { Cost } from "./cost";
11	import { blockedText, dateViolation, loadRules, ruleText } from "./rules";
12	import { getEntity, holidayPlan, mirrorBusiness, restoreHolidayEntry, setHolidayPlan, type YextHoliday } from "./yext";
13	
14	export type Biz = typeof schema.cnBusinesses.$inferSelect;
15	export type Sug = typeof schema.cnSuggestions.$inferSelect;
16	
17	const token = (n = 16) => [...crypto.getRandomValues(new Uint8Array(n))].map((b) => "REDACTED"[b % 31]).join("");
18	export const entityId = () => process.env.YEXT_ENTITY_ID ?? "SinceAI16";
19	export const appUrl = () => process.env.APP_URL ?? "http://localhost:3000";
20	const MAX_PER_MESSAGE = 4;
21	/** Out-of-fold dev data: at ≥0.95 the suggestion is exactly right 94.5% of the time; below that we always ask. */
22	export const AUTO_MIN_CONFIDENCE = 0.95;
23	const UNDO_WINDOW_MS = 24 * 3600_000;
24	
25	// ---- hours <-> plan ---------------------------------------------------------
26	export const toPlan = (h: string): DayPlan => (h === "closed" ? { closed: true } : { closed: false, intervals: h.split(",").map((x) => { const [start, end] = x.split("-"); return { start, end }; }) });
27	export const fromPlan = (p: DayPlan): string => (p.closed ? "closed" : p.intervals.map((i) => `${i.start}-${i.end}`).join(","));
28	
29	export async function log(db: DB, businessId: string, type: string, detail?: unknown, suggestionId?: string) {
30	  await db.insert(schema.cnEvents).values({ id: newId(), businessId, suggestionId: suggestionId ?? null, type, detailJson: detail ?? null, createdAt: now() }).run();
31	}
