1	import { and, eq, gte, inArray, lte } from "drizzle-orm";
2	import { schema, type DB } from "../db";
3	import { newId, now } from "../ids";
4	import { asLang, fmtDate, fmtHours, T, type Lang } from "./i18n";
5	import { appUrl, getBiz, log, sugsFor, type Biz, type Sug } from "./service";
6	import { hasTelegram, say, sendVoice } from "./telegram";
7	import { hasVoice, speak } from "./elevenlabs";
8	import { hasSms, sendSms } from "./sms";
9	import { demoPhone, dial, hasCalls } from "./calls";
10	import { sendNow } from "./deliver";
11	import { hasWhatsapp, sendWhatsapp } from "./whatsapp";
12	import { dateViolation, loadRules } from "./rules";
13	import { toPlan } from "./service";
14	
15	/**
16	 * Critical findings and the escalation ladder.
17	 * The "decision" is a transparent, tested policy over the hours model's calibrated confidence:
