122	  const callsToday = (await db.select().from(schema.cnAlerts).where(and(eq(schema.cnAlerts.businessId, biz.id), eq(schema.cnAlerts.step, "call"), eq(schema.cnAlerts.outcome, "sent"), gte(schema.cnAlerts.createdAt, now() - 86400_000))).all()).length;
123	  const sugs = (await sugsFor(db, biz.id)).filter((s) => s.action === "SUGGEST" && ["draft", "sent"].includes(s.status));
124	  for (const s of sugs) {
125	    const a = assess(s, biz.country, at);
126	    if (!a || (s.proposed && dateViolation(rules, s.date, toPlan(s.proposed)))) continue;   // the owner's rules also stop alerts about changes they forbade
127	    const n = nextStep(a, s.status, s.sentAt, await done(db, biz.id, s.id), at, tz, { callsToday, demo: opt.demo, canCall: hasCalls() && !!demoPhone() });
128	    if (!n || !n.due) continue;
129	    try {
130	      let r: { outcome: "sent" | "skipped" | "failed"; why?: string; callSid?: string };
131	      if (n.step === "contact") { const c = await sendNow(db, biz.id); r = c.ok && c.sent ? { outcome: "sent" } : { outcome: "skipped", why: "nothing to send" }; }
132	      else if (n.step === "nudge") r = await doNudge(db, biz, s, a);
133	      else if (n.step === "voice") r = await doVoice(biz, s);
134	      else r = n.why === "no telephony configured" ? { outcome: "skipped", why: n.why } : await doCall(biz, s);
135	      if (n.step !== "contact") await record(db, biz, a.scenario, s.id, n.step, r.outcome, { score: a.score, hoursUntil: a.hoursUntil, why: r.why, callSid: r.callSid, demo: !!opt.demo });
136	      await log(db, biz.id, `alert_${n.step}`, { date: s.date, outcome: r.outcome, why: r.why, score: a.score }, s.id);
137	      out.push({ sugId: s.id, date: s.date, step: n.step, outcome: r.outcome, why: r.why });
138	    } catch (e) {
139	      if (n.step !== "contact") await record(db, biz, a.scenario, s.id, n.step, "failed", { error: String(e) });
140	      out.push({ sugId: s.id, date: s.date, step: n.step, outcome: "failed", why: String(e) });
141	    }
142	    break;   // one step per business per run
143	  }
144	  return out;
145	}
