46	export function label(c: Change, lang: Lang): string {
47	  const t = L[lang];
48	  switch (c.type) {
49	    case "special_hours": return `${fmtDateShort(c.date, lang)}: ${fmtHours(c.hours, lang)}`;
50	    case "temporary_closure": return `${t.closure}: ${fmtDateShort(c.from, lang)} → ${fmtDateShort(c.to, lang)}`;
51	    case "regular_hours": return `${t.regular}: ${Object.entries(c.days).map(([d, h]) => `${d.slice(0, 3)} ${fmtHours(h as string, lang)}`).join(", ")}`;
52	    case "phone": return `${t.phone}: ${c.value}`; case "website": return `${t.website}: ${c.value}`; case "email": return `${t.email}: ${c.value}`;
53	    case "description": return `${t.description}: ${c.value.slice(0, 90)}${c.value.length > 90 ? "…" : ""}`;
54	    case "rule": return `🔒 ${ruleText(c.rule, lang)}`;
55	    case "rule_remove": return `🔓 ${t.ruleOff}`;
56	    case "address": return `${t.address}: ${c.line1}, ${c.postalCode ?? ""} ${c.city}`.replace(/\s+/g, " ");
57	  }
58	}
