109	export async function undoChange(db: DB, rec: Rec): Promise<boolean> {
110	  const u = rec.undoJson as { kind: string; dates?: string[]; before?: unknown } | null;
111	  if (rec.status !== "applied" || !u) return false;
112	  if (u.kind === "rule_added") await db.delete(schema.cnRules).where(eq(schema.cnRules.id, (u as unknown as { ruleId: string }).ruleId)).run();
113	  else if (u.kind === "rule_removed") await addRule(db, rec.businessId, (u as unknown as { rule: z.infer<typeof RuleZ> }).rule);
114	  else
115	  if (u.kind === "holidays") await restoreHolidayEntries(entityId(), u.dates ?? [], (u.before ?? []) as YextHoliday[]);
116	  else if (u.kind === "regular") await restoreRegularDays(entityId(), u.before as never);
117	  else await setProfileFields(entityId(), u.before as never);
118	  await db.update(schema.cnChanges).set({ status: "undone" }).where(eq(schema.cnChanges.id, rec.id)).run();
119	  await log(db, rec.businessId, "agent_undone", { type: rec.type });
120	  return true;
121	}
