211	/** Real assistants (live web search) are asked what customers ask and compared with what Connect holds for the business. */
212	export async function presenceFacts(db: DB, biz: Biz): Promise<PresenceFacts> {
213	  await ensureMirror(biz);
214	  const e = await getEntity(entityId());
215	  const canonical: Record<string, unknown> = {};
216	  if (e.hours) { const h = parseHours(DAYS.map((d) => { const x = e.hours![d]; return x?.isClosed || !x?.openIntervals?.length ? `${d} closed` : `${d} ${x.openIntervals.map((i) => `${i.start}-${i.end}`).join(",")}`; }).join("; ")); if (h) canonical.hours = h; }
217	  if (e.address?.line1) canonical.address = `${e.address.line1}, ${e.address.city ?? biz.city ?? ""}`;
218	  const assistants = DEFAULT_ASSISTANTS.filter((a) => a.web);
219	  const qs = auditQuestions(biz.name, biz.city, null).slice(0, 2);
220	  const rows = await Promise.all(assistants.flatMap((a) => qs.map(async (q) => {
221	    try {
222	      const r = await chatFull([{ role: "system", content: SYSTEM_ASK }, { role: "user", content: q.prompt }], { model: a.model, max: 450, timeoutMs: 40_000 });
223	      const f = await extractFromAnswer(r.content, { name: biz.name, city: biz.city });
224	      const confused = f?.other_business ? f.other_business_name || "another business" : null;
225	      const verdicts = f && f.mentioned && !confused ? judgeAnswer(f, q.fields, canonical as never).filter((v) => v.severity && !["exact", "equivalent", "harmless"].includes(v.classification)) : [];
226	      return { assistant: a.label, mentioned: !!f?.mentioned && !confused, confused, verdicts };
227	    } catch { return { assistant: a.label, mentioned: false, confused: null as string | null, verdicts: [] as ReturnType<typeof judgeAnswer> }; }
228	  })));
229	  const sugs = await sugsFor(db, biz.id);
230	  return {
231	    profile: { hoursSet: !!e.hours && !!canonical.hours, upcomingExceptions: (e.hours?.holidayHours ?? []).length, phone: e.mainPhone ?? null, website: e.websiteUrl?.url ?? null, description: !!e.description },
232	    listings: whereItShows(biz, asLang(biz.language)).map((x) => x.text),
233	    waiting: sugs.filter((s) => ["draft", "sent"].includes(s.status) && s.action === "SUGGEST").length, flagged: sugs.filter((s) => s.action === "FLAG").length,
234	    assistants: assistants.map((a) => { const mine = rows.filter((r) => r.assistant === a.label); return { assistant: a.label, describesYou: mine.some((r) => r.mentioned), confusedWith: mine.find((r) => r.confused)?.confused ?? null, wrong: mine.flatMap((r) => r.verdicts.map((v) => ({ field: v.field, said: v.stated, expected: v.expected }))) }; }),
235	  };
236	}
237	
238	const AI: Record<Lang, { head: string; confused: (a: string, x: string) => string; unknown: (a: string) => string; wrong: (a: string, n: number) => string; fine: (a: string) => string; fix: string }> = {
239	  en: { head: "What AI assistants say about you:", confused: (a, x) => `• ${a}: describes a different business (${x}).`, unknown: (a) => `• ${a}: could not find you.`, wrong: (a, n) => `• ${a}: ${n} wrong detail${n > 1 ? "s" : ""}.`, fine: (a) => `• ${a}: describes you correctly.`, fix: "Want me to keep your details complete and check again later?" },
240	  fi: { head: "Mitä tekoälyavustajat kertovat sinusta:", confused: (a, x) => `• ${a}: kuvaa eri yritystä (${x}).`, unknown: (a) => `• ${a}: ei löytänyt sinua.`, wrong: (a, n) => `• ${a}: ${n} virheellistä tietoa.`, fine: (a) => `• ${a}: kuvaa sinut oikein.`, fix: "Haluatko, että pidän tietosi ajan tasalla ja tarkistan myöhemmin uudelleen?" },
241	  sv: { head: "Vad AI-assistenter säger om dig:", confused: (a, x) => `• ${a}: beskriver ett annat företag (${x}).`, unknown: (a) => `• ${a}: hittade dig inte.`, wrong: (a, n) => `• ${a}: ${n} felaktiga uppgifter.`, fine: (a) => `• ${a}: beskriver dig rätt.`, fix: "Vill du att jag håller dina uppgifter kompletta och kollar igen senare?" },
242	  nb: { head: "Hva AI-assistenter sier om deg:", confused: (a, x) => `• ${a}: beskriver en annen bedrift (${x}).`, unknown: (a) => `• ${a}: fant deg ikke.`, wrong: (a, n) => `• ${a}: ${n} feil opplysninger.`, fine: (a) => `• ${a}: beskriver deg riktig.`, fix: "Vil du at jeg holder opplysningene dine komplette og sjekker igjen senere?" },
243	};
244	
245	/** The AI-assistant findings are written from the facts, not by the model, so the most important line is never skipped or embellished. */
246	export function assistantBlock(facts: PresenceFacts, lang: Lang): string {
247	  const t = AI[lang];
248	  const lines = facts.assistants.map((a) => (a.wrong.length ? t.wrong(a.assistant, a.wrong.length) : a.confusedWith ? t.confused(a.assistant, a.confusedWith) : !a.describesYou ? t.unknown(a.assistant) : t.fine(a.assistant)));
249	  return `${t.head}\n${lines.join("\n")}\n${t.fix}`;
250	}
251	
252	export async function presenceMessage(biz: Biz, facts: PresenceFacts): Promise<string> {
253	  const lang = asLang(biz.language);
254	  const r = await chatFull([{ role: "system", content: `Write a short, friendly message (max 130 words) in language "${lang}" for a busy business owner about how their business looks online. Use ONLY the facts in the JSON; never invent. Say plainly what is fine and what is missing in their profile and listings, and the single most useful next step (the owner can ask you to change something). Do NOT mention AI assistants: that part is added separately. No markdown.` }, { role: "user", content: JSON.stringify({ business: biz.name, city: biz.city, profile: facts.profile, listings: facts.listings, waitingSuggestions: facts.waiting, flaggedForHuman: facts.flagged }) }], { max: 400, timeoutMs: 30_000 });
255	  return `${r.content.trim()}\n\n${assistantBlock(facts, lang)}`;
256	}
257	
258	/** "Audit brasa.fi": a full public check on any website, returned as a shareable report link. */
259	export async function siteAuditLink(db: DB, site: string, chatKey: string): Promise<string | null> {
260	  try { const r = await createPublicCheck(db, site, `telegram:${chatKey}`); return `${appUrl()}/report/${r.auditId}`; } catch { return null; }
261	}
