import { runDueAlerts } from "./src/lib/connect/critical";
import { cleanupTrials } from "./src/lib/connect/trial";
// @ts-expect-error generated by `opennextjs-cloudflare build`
import handler from "./.open-next/worker.js";
import { dbFromEnv, type CfEnv, type ScanJob } from "./src/lib/db";
import { enqueueDueScans, executeScan } from "./src/lib/scan";
import { enqueueDueAudits, runAssistantJob } from "./src/lib/ai-audit";
import { runPublicSources } from "./src/lib/public-sources-job";
import { runAgentJob } from "./src/lib/connect/agent-jobs";

export default {
  fetch: handler.fetch,
  async scheduled(_evt: ScheduledController, env: CfEnv, ctx: ExecutionContext) {
    const db = dbFromEnv(env);
    ctx.waitUntil(enqueueDueScans(db));
    ctx.waitUntil(enqueueDueAudits(db));
    ctx.waitUntil(runDueAlerts(db));
    ctx.waitUntil(cleanupTrials(db));
  },
  async queue(batch: MessageBatch<ScanJob>, env: CfEnv) {
    const db = dbFromEnv(env);
    for (const m of batch.messages) {
      const { locationId, scanId, paceMs, trigger, kind, auditId, assistantId, payload } = m.body;
      try {
        if (kind === "agent" && payload) {
          await runAgentJob(db, payload as never);
          m.ack();
          continue;
        }
        if (kind === "public_sources" && auditId) {
          await runPublicSources(db, auditId);
          m.ack();
          continue;
        }
        if (kind === "ai_audit" && auditId && assistantId) {
          await runAssistantJob(db, auditId, assistantId);
          m.ack();
          continue;
        }
        await executeScan(db, locationId, scanId, { paceMs, trigger: trigger as "manual" | "scheduled" });
        m.ack();
      } catch {
        m.retry();
      }
    }
  },
};

