15	/**
16	 * Critical findings and the escalation ladder.
17	 * The "decision" is a transparent, tested policy over the hours model's calibrated confidence:
18	 *   score = confidence x urgency(hours until the day starts).  Critical at >= 0.5; a phone call needs >= 0.75,
19	 *   real stakes (views that day) and a reachable number. Everything is a typed output (scenario, score, level), no free text.
20	 * Ladder: message -> nudge (reminder) -> voice note -> phone call. One step per run, each step only when due.
21	 */
22	export const POLICY = { critical: 0.5, call: 0.75, callMinViews: 20, nudgeAfterH: 3, voiceAfterH: 4, callAfterH: 4, quietFrom: 8, quietTo: 20, callMinHoursLeft: 2, horizonH: 72 } as const;
23	export type Step = "contact" | "nudge" | "voice" | "call";
24	const LADDER: Step[] = ["nudge", "voice", "call"];
25	const TZ: Record<string, string> = { FI: "Europe/Helsinki", SE: "Europe/Stockholm", NO: "Europe/Oslo" };
26	
27	export interface Assessment { scenario: "hours_imminent"; sugId: string; date: string; score: number; critical: boolean; callEligible: boolean; hoursUntil: number; views: number }
