29	/** Local wall-clock parts for an instant. */
30	function localParts(ms: number, tz: string) {
31	  const f = new Intl.DateTimeFormat("en-GB", { timeZone: tz, hourCycle: "h23", year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit" }).formatToParts(new Date(ms));
32	  const g = (t: string) => Number(f.find((x) => x.type === t)!.value);
33	  return { y: g("year"), mo: g("month"), d: g("day"), h: g("hour"), mi: g("minute") };
34	}
35	/** Hours from `nowMs` until the given local date starts (negative once it has started). */
36	export function hoursUntil(date: string, tz: string, nowMs: number): number {
37	  const p = localParts(nowMs, tz), nowLocal = Date.UTC(p.y, p.mo - 1, p.d, p.h, p.mi), [y, m, d] = date.split("-").map(Number);
38	  return (Date.UTC(y, m - 1, d) - nowLocal) / 3.6e6;
39	}
40	export const urgency = (h: number) => (h <= 24 ? 1 : h <= 48 ? 0.7 : h <= POLICY.horizonH ? 0.4 : 0);
41	export const inQuietHours = (tz: string, nowMs: number) => { const h = localParts(nowMs, tz).h; return h < POLICY.quietFrom || h >= POLICY.quietTo; };
42	
43	export function assess(s: Pick<Sug, "id" | "date" | "action" | "status" | "shown" | "proposed" | "confidence" | "costJson">, country: string, nowMs: number): Assessment | null {
44	  if (s.action !== "SUGGEST" || !s.proposed || s.proposed === s.shown || !["draft", "sent"].includes(s.status)) return null;
45	  const h = hoursUntil(s.date, TZ[country] ?? "Europe/Helsinki", nowMs), score = Math.round(s.confidence * urgency(h) * 100) / 100;
46	  const views = Number((s.costJson as { views?: number } | null)?.views ?? 0);
47	  return { scenario: "hours_imminent", sugId: s.id, date: s.date, score, hoursUntil: Math.round(h * 10) / 10, views, critical: score >= POLICY.critical, callEligible: score >= POLICY.call && views >= POLICY.callMinViews && h >= POLICY.callMinHoursLeft };
48	}
