66	export interface LadderResult { sugId: string; date: string; step: Step; outcome: "sent" | "skipped" | "failed"; why?: string }
67	
68	/** The next step for one critical suggestion and whether it is due. Pure, so the policy is testable. */
69	export function nextStep(a: Assessment, status: string, sentAt: number | null, past: { step: string; outcome: string; createdAt: number }[], nowMs: number, tz: string, opt: { callsToday: number; demo?: boolean; canCall: boolean }): { step: Step; due: boolean; why?: string } | null {
70	  if (!a.critical) return null;
71	  if (status === "draft") return { step: "contact", due: true };
72	  const taken = new Set(past.map((p) => p.step)), hoursSince = (t: number) => (nowMs - t) / 3.6e6;
73	  const step = LADDER.find((x) => !taken.has(x));
74	  if (!step) return null;
75	  const last = [...past].sort((x, y) => y.createdAt - x.createdAt)[0]?.createdAt ?? sentAt ?? nowMs;
76	  const wait = step === "nudge" ? POLICY.nudgeAfterH : step === "voice" ? POLICY.voiceAfterH : POLICY.callAfterH;
77	  if (!opt.demo && hoursSince(last) < wait) return { step, due: false, why: `waiting ${wait} h after the previous step` };
78	  if (step === "call") {
79	    if (!a.callEligible) return { step, due: false, why: `not eligible for a call (score ${a.score}, ${a.views} views, ${a.hoursUntil} h left)` };
80	    if (opt.callsToday >= 1) return { step, due: false, why: "one call per 24 h" };
81	    if (!opt.canCall) return { step, due: true, why: "no telephony configured" };
82	    if (!opt.demo && inQuietHours(tz, nowMs)) return { step, due: false, why: "quiet hours (before 08:00 / after 20:00)" };
83	  }
84	  return { step, due: true };
85	}
