91	  if (demoPhone() && hasSms()) {
92	    const link = s.messageId ? (await db.select().from(schema.cnMessages).where(eq(schema.cnMessages.id, s.messageId)).get())?.token : null;
93	    await sendSms(demoPhone()!, `${biz.name}: ${text.replace("⏰ ", "")}${link ? `\n${appUrl()}/d/${link}` : ""}`); sent = true;
