147	/** Cron: businesses with a decision waiting for a day inside the horizon. */
148	export async function runDueAlerts(db: DB, cap = 20) {
149	  const nowMs = now(), day = (ms: number) => new Date(ms).toISOString().slice(0, 10);
150	  const rows = await db.select({ b: schema.cnSuggestions.businessId }).from(schema.cnSuggestions).where(and(eq(schema.cnSuggestions.action, "SUGGEST"), inArray(schema.cnSuggestions.status, ["draft", "sent"]), gte(schema.cnSuggestions.date, day(nowMs - 86400_000)), lte(schema.cnSuggestions.date, day(nowMs + 4 * 86400_000)))).all();
151	  const ids = [...new Set(rows.map((r) => r.b))].slice(0, cap), res: LadderResult[] = [];
152	  for (const id of ids) res.push(...(await runLadder(db, id)));
153	  return res;
154	}
