23	export const weekdayOf = (iso: string) => DAYS[(new Date(`${iso}T12:00:00Z`).getUTCDay() + 6) % 7];
24	const mins = (t: string) => Number(t.slice(0, 2)) * 60 + Number(t.slice(3));
25	
26	/** The last closing time of a plan in minutes after the day starts (past-midnight closes count as 24h+). */
27	function closesAt(p: DayPlan): number | null {
28	  if (p.closed) return null;
29	  const last = p.intervals[p.intervals.length - 1], s = mins(last.start), e = mins(last.end);
30	  return e <= s ? e + 1440 : e;
31	}
32	
33	/** First rule that this plan on this weekday would break, or null. `date` (optional) is for date locks. */
34	export function planViolation(rules: Rule[], weekday: (typeof DAYS)[number], plan: DayPlan, date?: string): Rule | null {
35	  for (const r of rules) {
36	    if (r.kind === "lock_date" && date && r.date === date) return r;
37	    if (r.kind === "never_closed" && r.weekday === weekday && plan.closed) return r;
38	    if (r.kind === "open_until" && (!r.weekday || r.weekday === weekday)) {
39	      const c = closesAt(plan);
40	      if (c === null ? !!r.weekday : c < mins(r.time)) return r;
41	    }
42	  }
43	  return null;
44	}
45	export const dateViolation = (rules: Rule[], date: string, plan: DayPlan) => planViolation(rules, weekdayOf(date), plan, date);
