47	export type RuleChange =
48	  | { type: "special_hours"; date: string; hours: string } | { type: "temporary_closure"; from: string; to: string }
49	  | { type: "regular_hours"; days: Partial<Record<string, string>> } | { type: string; [k: string]: unknown };
50	const toPlan = (h: string): DayPlan => (h === "closed" ? { closed: true } : { closed: false, intervals: h.split(",").map((x) => { const [start, end] = x.split("-"); return { start, end }; }) });
51	
52	/** The rule an owner-requested change would break, or null. */
53	export function changeViolation(rules: Rule[], c: RuleChange): Rule | null {
54	  if (!rules.length) return null;
55	  if (c.type === "special_hours") return dateViolation(rules, c.date as string, toPlan(c.hours as string));
56	  if (c.type === "temporary_closure") {
57	    for (let d = c.from as string; d <= (c.to as string); d = new Date(new Date(`${d}T12:00:00Z`).getTime() + 86400_000).toISOString().slice(0, 10)) { const v = dateViolation(rules, d, { closed: true }); if (v) return v; }
58	    return null;
59	  }
60	  if (c.type === "regular_hours") { for (const [d, h] of Object.entries(c.days as Record<string, string>)) { const v = planViolation(rules, d as (typeof DAYS)[number], toPlan(h)); if (v) return v; } return null; }
61	  return rules.find((r) => r.kind === "lock_field" && r.field === c.type) ?? null;
62	}
