60	/** Every proposed change passes the same checks as a model suggestion before the owner is even asked. */
61	export function validateChange(raw: unknown, biz: { country: string }, todayIso: string): { ok: true; change: Change } | { ok: false; why: string } {
62	  const p = ChangeZ.safeParse(raw);
63	  if (!p.success) return { ok: false, why: "unreadable" };
64	  const c = p.data;
65	  const inRange = (d: string) => d >= todayIso && d <= addDays(todayIso, 400) && !Number.isNaN(Date.parse(d));
66	  if (c.type === "special_hours") { if (!inRange(c.date)) return { ok: false, why: "date out of range" }; const e = validatePlan(toPlan(c.hours)); if (e) return { ok: false, why: e }; }
67	  if (c.type === "temporary_closure") { if (!inRange(c.from) || c.to < c.from || c.to > addDays(c.from, 30)) return { ok: false, why: "closure must be within 31 days and in the future" }; }
68	  if (c.type === "regular_hours") { for (const h of Object.values(c.days)) { const e = validatePlan(toPlan(h as string)); if (e) return { ok: false, why: e }; } }
69	  if (c.type === "phone") { const n = normalizePhone(c.value, { FI: "358", SE: "46", NO: "47" }[biz.country] ?? "358"); if (!n) return { ok: false, why: "phone" }; return { ok: true, change: { ...c, value: n } }; }
70	  return { ok: true, change: c };
71	}
