76	export async function applyChange(db: DB, biz: Biz, rec: Rec): Promise<{ ok: boolean; error?: string }> {
77	  const c = rec.payloadJson as unknown as Change;
78	  try {
79	    let undo: Record<string, unknown>;
80	    if (c.type === "rule" || c.type === "rule_remove") {
81	      if (c.type === "rule") undo = { kind: "rule_added", ruleId: await addRule(db, biz.id, c.rule) };
82	      else { const had = (await loadRules(db, biz.id)).find((x) => x.id === c.id); if (!had) throw new Error("rule not found"); await removeRule(db, biz.id, c.id); undo = { kind: "rule_removed", rule: had.rule }; }
83	      await db.update(schema.cnChanges).set({ status: "applied", undoJson: undo, appliedAt: now() }).where(eq(schema.cnChanges.id, rec.id)).run();
84	      await log(db, biz.id, "rule_changed", { type: c.type });
85	      return { ok: true };
86	    }
87	    // The floor is checked again at apply time: a rule added after the proposal still wins.
88	    const broken = changeViolation((await loadRules(db, biz.id)).map((x) => x.rule), c as never);
89	    if (broken) { await db.update(schema.cnChanges).set({ status: "failed", note: `rule: ${ruleText(broken, "en")}` }).where(eq(schema.cnChanges.id, rec.id)).run(); await log(db, biz.id, "blocked_by_rule", { type: c.type, rule: ruleText(broken, "en") }); return { ok: false, error: `rule:${blockedText(broken, asLang(biz.language))}` }; }
90	    await ensureMirror(biz);
91	    if (c.type === "special_hours") { const r = await setHolidayPlans(entityId(), [{ date: c.date, plan: toPlan(c.hours) }]); undo = { kind: "holidays", dates: [c.date], before: r.before }; }
92	    else if (c.type === "temporary_closure") {
93	      const dates: string[] = []; for (let d = c.from; d <= c.to; d = addDays(d, 1)) dates.push(d);
94	      const r = await setHolidayPlans(entityId(), dates.map((date) => ({ date, plan: { closed: true as const } }))); undo = { kind: "holidays", dates, before: r.before };
95	    } else if (c.type === "regular_hours") { const r = await setRegularDays(entityId(), Object.fromEntries(Object.entries(c.days).map(([d, h]) => [d, toPlan(h as string)])) as never); undo = { kind: "regular", before: r.before }; }
96	    else {
97	      const f = c.type === "phone" ? { mainPhone: c.value } : c.type === "website" ? { websiteUrl: { url: c.value } } : c.type === "email" ? { emails: [c.value] } : c.type === "description" ? { description: c.value } : { address: { line1: c.line1, city: c.city, postalCode: c.postalCode, countryCode: biz.country } };
98	      const r = await setProfileFields(entityId(), f as never); undo = { kind: "fields", before: r.before };
99	    }
100	    await db.update(schema.cnChanges).set({ status: "applied", undoJson: undo, appliedAt: now() }).where(eq(schema.cnChanges.id, rec.id)).run();
101	    await log(db, biz.id, "agent_applied", { type: c.type, source: rec.source });
102	    return { ok: true };
103	  } catch (e) {
104	    await db.update(schema.cnChanges).set({ status: "failed", note: e instanceof Error ? e.message : "failed" }).where(eq(schema.cnChanges.id, rec.id)).run();
105	    return { ok: false, error: e instanceof Error ? e.message : "failed" };
106	  }
107	}
