175	export async function handleOwnerInput(db: DB, bizId: string, input: Input): Promise<AgentReply> {
176	  const biz = (await getBiz(db, bizId))!, lang = asLang(biz.language), t = L[lang], tz = TZ[biz.country] ?? "Europe/Helsinki";
177	  await log(db, biz.id, "agent_in", { source: input.source, text: input.text?.slice(0, 200), image: !!input.image });
178	  const speak = input.source === "voice" || !!biz.voice;
179	  let out: Awaited<ReturnType<typeof understand>> = null;
180	  try { out = await understand(biz, await context(db, biz, tz), input, tz); } catch { out = null; }
181	  if (input.image && out) await log(db, biz.id, "agent_vision", { model: (out as { via?: string }).via ?? "unknown" });
182	  if (!out) return { text: t.unclear, changes: [], speak };
183	
184	  if (out.intent === "stop") { await db.update(schema.cnBusinesses).set({ optedOut: 1 }).where(eq(schema.cnBusinesses.id, biz.id)).run(); return { text: t.off, changes: [], speak }; }
185	  if (out.intent === "resume") { await db.update(schema.cnBusinesses).set({ optedOut: 0 }).where(eq(schema.cnBusinesses.id, biz.id)).run(); return { text: t.on, changes: [], speak }; }
186	  if (out.intent === "radar") return { text: radarText(await computeIssues(db, biz), lang), changes: [], speak };
187	  if (out.intent === "presence") return { text: t.checking, changes: [], presence: true, speak };
188	  if (out.intent === "site_audit" && out.site) return { text: t.checking, changes: [], site: out.site, speak };
189	
190	  if (out.intent === "change") {
191	    const good: { id: string; label: string }[] = [], held: string[] = [];
192	    const rules = (await loadRules(db, biz.id)).map((r) => r.rule);
193	    for (const raw of out.changes ?? []) {
194	      const v = validateChange(raw, biz, today(tz));
195	      if (!v.ok) continue;
196	      const broken = changeViolation(rules, v.change as never);
197	      if (broken) { held.push(blockedText(broken, lang)); await log(db, biz.id, "blocked_by_rule", { type: v.change.type, rule: ruleText(broken, "en") }); continue; }
198	      const id = newId();
199	      await db.insert(schema.cnChanges).values({ id, businessId: biz.id, type: v.change.type, payloadJson: v.change as unknown as Record<string, unknown>, source: input.source, status: "proposed", createdAt: now() }).run();
200	      good.push({ id, label: label(v.change, lang) });
201	    }
202	    if (!good.length) return { text: held[0] ?? (out.answer || t.unclear), changes: [], speak };
203	    return { text: `${out.answer ? out.answer + "\n\n" : ""}${t.understood}\n${good.map((g) => `• ${g.label}`).join("\n")}${held.length ? `\n\n${held.join("\n")}` : ""}`, changes: good, speak };
204	  }
205	  return { text: out.answer || t.unclear, changes: [], speak };
206	}
