211	/** Real assistants (live web search) are asked what customers ask and compared with what Connect holds for the business. */
212	export async function presenceFacts(db: DB, biz: Biz): Promise<PresenceFacts> {
213	  await ensureMirror(biz);
214	  const e = await getEntity(entityId());
215	  const canonical: Record<string, unknown> = {};
216	  if (e.hours) { const h = parseHours(DAYS.map((d) => { const x = e.hours![d]; return x?.isClosed || !x?.openIntervals?.length ? `${d} closed` : `${d} ${x.openIntervals.map((i) => `${i.start}-${i.end}`).join(",")}`; }).join("; ")); if (h) canonical.hours = h; }
217	  if (e.address?.line1) canonical.address = `${e.address.line1}, ${e.address.city ?? biz.city ?? ""}`;
218	  const assistants = DEFAULT_ASSISTANTS.filter((a) => a.web);
219	  const qs = auditQuestions(biz.name, biz.city, null).slice(0, 2);
220	  const rows = await Promise.all(assistants.flatMap((a) => qs.map(async (q) => {
221	    try {
222	      const r = await chatFull([{ role: "system", content: SYSTEM_ASK }, { role: "user", content: q.prompt }], { model: a.model, max: 450, timeoutMs: 40_000 });
223	      const f = await extractFromAnswer(r.content, { name: biz.name, city: biz.city });
224	      const confused = f?.other_business ? f.other_business_name || "another business" : null;
225	      const verdicts = f && f.mentioned && !confused ? judgeAnswer(f, q.fields, canonical as never).filter((v) => v.severity && !["exact", "equivalent", "harmless"].includes(v.classification)) : [];
226	      return { assistant: a.label, mentioned: !!f?.mentioned && !confused, confused, verdicts };
227	    } catch { return { assistant: a.label, mentioned: false, confused: null as string | null, verdicts: [] as ReturnType<typeof judgeAnswer> }; }
228	  })));
229	  const sugs = await sugsFor(db, biz.id);
230	  return {
231	    profile: { hoursSet: !!e.hours && !!canonical.hours, upcomingExceptions: (e.hours?.holidayHours ?? []).length, phone: e.mainPhone ?? null, website: e.websiteUrl?.url ?? null, description: !!e.description },
232	    listings: whereItShows(biz, asLang(biz.language)).map((x) => x.text),
233	    waiting: sugs.filter((s) => ["draft", "sent"].includes(s.status) && s.action === "SUGGEST").length, flagged: sugs.filter((s) => s.action === "FLAG").length,
234	    assistants: assistants.map((a) => { const mine = rows.filter((r) => r.assistant === a.label); return { assistant: a.label, describesYou: mine.some((r) => r.mentioned), confusedWith: mine.find((r) => r.confused)?.confused ?? null, wrong: mine.flatMap((r) => r.verdicts.map((v) => ({ field: v.field, said: v.stated, expected: v.expected }))) }; }),
235	  };
236	}
