246	export function assistantBlock(facts: PresenceFacts, lang: Lang): string {
247	  const t = AI[lang];
248	  const lines = facts.assistants.map((a) => (a.wrong.length ? t.wrong(a.assistant, a.wrong.length) : a.confusedWith ? t.confused(a.assistant, a.confusedWith) : !a.describesYou ? t.unknown(a.assistant) : t.fine(a.assistant)));
249	  return `${t.head}\n${lines.join("\n")}\n${t.fix}`;
