7	/**
8	 * Issue Radar: every kind of problem we can actually detect for one business, in one list.
9	 * Each issue comes from a real check (the hours model, the live Yext profile, the publishers' connection state,
10	 * the last AI-assistant audit); nothing here is guessed or filled in. `coverage` says what is not watched yet.
11	 */
12	export type IssueCode = "hours_waiting" | "closed_for_good" | "blocked_by_rule" | "profile_missing" | "listing_off" | "ai_wrong" | "ai_confused" | "ai_unchecked";
13	export interface Issue { code: IssueCode; severity: "high" | "medium" | "low"; n?: number; detail?: string; names?: string[] }
14	
15	const PROFILE_FIELDS: [string, (e: YextEntity) => boolean][] = [["phone", (e) => !!e.mainPhone], ["website", (e) => !!e.websiteUrl?.url], ["description", (e) => !!e.description], ["regular hours", (e) => !!e.hours && ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"].some((d) => !!(e.hours as Record<string, unknown>)[d])]];
16	const AI_FRESH_MS = 30 * 86400_000;
17	
18	export interface Radar { issues: Issue[]; coverage: { watching: string[]; notYet: string[] } }
19	
20	export async function computeIssues(db: DB, biz: Biz, opts: { live?: boolean } = {}): Promise<Radar> {
21	  const issues: Issue[] = [];
22	  const sugs = await sugsFor(db, biz.id);
23	  const waiting = sugs.filter((s) => s.action === "SUGGEST" && ["draft", "sent"].includes(s.status));
24	  if (waiting.length) issues.push({ code: "hours_waiting", severity: "high", n: waiting.length, detail: waiting.map((s) => s.date).sort()[0] });
25	  const flagged = sugs.filter((s) => s.action === "FLAG").length;
26	  if (flagged) issues.push({ code: "closed_for_good", severity: "high", n: flagged });
27	  const blocked = sugs.filter((s) => s.status === "blocked").length;
28	  if (blocked) issues.push({ code: "blocked_by_rule", severity: "low", n: blocked });
29	
30	  if (opts.live !== false) {
31	    try {
32	      await ensureMirror(biz);
33	      const e = await getEntity(entityId());
34	      const missing = PROFILE_FIELDS.filter(([, ok]) => !ok(e)).map(([n]) => n);
35	      if (missing.length) issues.push({ code: "profile_missing", severity: missing.length > 1 ? "medium" : "low", n: missing.length, names: missing });
36	    } catch { /* radar still answers without the live profile */ }
37	  }
38	  const off = ((biz.publishersJson ?? []) as { name: string; status: string }[]).filter((p) => p.status === "OPTED_OUT" || p.status === "UNAVAILABLE").map((p) => p.name);
39	  if (off.length) issues.push({ code: "listing_off", severity: "medium", n: off.length, names: off });
40	
41	  const last = (await db.select().from(schema.cnEvents).where(eq(schema.cnEvents.businessId, biz.id)).orderBy(desc(schema.cnEvents.createdAt)).all()).find((x) => x.type === "agent_presence");
42	  if (!last || Date.now() - last.createdAt > AI_FRESH_MS) issues.push({ code: "ai_unchecked", severity: "low" });
43	  else {
44	    const rows = ((last.detailJson as { assistants?: { a: string; wrong: number; confused: string | null }[] } | null)?.assistants ?? []);
45	    const wrong = rows.filter((r) => r.wrong > 0), confused = rows.filter((r) => r.confused);
46	    if (wrong.length) issues.push({ code: "ai_wrong", severity: "high", n: wrong.length, names: wrong.map((r) => r.a) });
47	    if (confused.length) issues.push({ code: "ai_confused", severity: "high", n: confused.length, names: confused.map((r) => r.a) });
48	  }
49	  const rank = { high: 0, medium: 1, low: 2 };
50	  issues.sort((a, b) => rank[a.severity] - rank[b.severity]);
51	  return { issues, coverage: { watching: ["opening hours for special days (statistical model)", "profile completeness (live from the listing source)", "which publishers are connected", "what AI assistants say (on request / weekly)"], notYet: ["photo freshness and quality", "review replies", "menu and price changes"] } };
52	}
