73	/** Written from the facts by code, not by a model, so the list can never be embellished. */
74	export function radarText(r: Radar, lang: Lang | string): string {
75	  const d = D[asLang(lang)];
76	  const real = r.issues.filter((i) => i.code !== "ai_unchecked");
77	  if (!r.issues.length) return d.none;
78	  return `${real.length ? d.head : ""}${real.length ? "\n" : ""}${r.issues.map(d.line).join("\n")}\n\n${d.ask}`.trim();
79	}
