12	export interface YextEntity { mainPhone?: string | null; websiteUrl?: { url?: string } | null; emails?: string[] | null; description?: string | null; name: string; address?: { line1?: string; city?: string; postalCode?: string; countryCode?: string }; timezone?: string; hours?: YextHours; categories?: Record<string, string[]>; meta?: { id: string; language?: string } }
13	
14	export async function call<T>(method: "GET" | "PUT", path: string, body?: unknown): Promise<T> {
15	  const url = `${base()}/v2/accounts/me/entities/${encodeURIComponent(path)}?${new URLSearchParams({ api_key: key(), v: V })}`;
16	  for (let attempt = 0; ; attempt++) {
17	    const res = await fetch(url, { method, headers: body ? { "content-type": "application/json" } : undefined, body: body ? JSON.stringify(body) : undefined, signal: AbortSignal.timeout(12_000) });
18	    const j = (await res.json().catch(() => ({}))) as { response?: T; meta?: { errors?: { message?: string }[] } };
19	    if (res.ok && j.response) return j.response;
20	    if (res.status >= 500 && attempt < 1) continue;
21	    throw new Error(`Yext ${res.status}: ${j.meta?.errors?.map((e) => e.message).join("; ") || "request failed"}`);
22	  }
23	}
24	
25	export const getEntity = (id: string) => call<YextEntity>("GET", id);
26	
27	export const toYext = (date: string, p: DayPlan): YextHoliday => (p.closed ? { date, isClosed: true } : { date, openIntervals: p.intervals.map((i) => ({ start: i.start, end: i.end })) });
28	export const fromYext = (e: { openIntervals?: YextInterval[]; isClosed?: boolean }): DayPlan | null => (e.isClosed ? { closed: true } : e.openIntervals?.length ? { closed: false, intervals: e.openIntervals.map((i) => ({ start: i.start, end: i.end })) } : null);
29	
30	/** Regular weekly hours by weekday (0=Sunday..6=Saturday), or null when the entity has none. */
31	export function regularHours(h?: YextHours): Record<number, DayPlan> | null {
32	  if (!h) return null;
33	  const out: Record<number, DayPlan> = {};
34	  DAYS.forEach((d, i) => { const p = h[d] ? fromYext(h[d]!) : null; if (p) out[(i + 1) % 7] = p; });
35	  return Object.keys(out).length ? out : null;
36	}
37	export const holidayPlan = (h: YextHours | undefined, date: string): DayPlan | null => { const e = h?.holidayHours?.find((x) => x.date === date); return e ? fromYext(e) : null; };
38	
39	/** Sets (or, with null, removes) the exception for one date. Reads first and writes the whole hours object back, so regular hours and other dates are never lost. */
40	export async function setHolidayPlan(entityId: string, date: string, plan: DayPlan | null): Promise<{ before: YextHoliday | null; after: YextEntity }> {
41	  const current = await getEntity(entityId);
42	  const hours: YextHours = { ...(current.hours ?? {}) };
43	  const list = (hours.holidayHours ?? []).filter((x) => x.date !== date);
44	  const before = (hours.holidayHours ?? []).find((x) => x.date === date) ?? null;
45	  if (plan) list.push(toYext(date, plan));
46	  hours.holidayHours = list.sort((a, b) => a.date.localeCompare(b.date));
47	  const after = await call<YextEntity>("PUT", entityId, { hours });
48	  return { before, after };
49	}
