51	/** Puts back exactly what was there before (or removes the date when there was nothing). Used by undo. */
52	export async function restoreHolidayEntry(entityId: string, date: string, before: YextHoliday | null) {
53	  const current = await getEntity(entityId);
54	  const hours: YextHours = { ...(current.hours ?? {}) };
55	  const list = (hours.holidayHours ?? []).filter((x) => x.date !== date);
56	  if (before) list.push(before);
57	  hours.holidayHours = list.sort((a, b) => a.date.localeCompare(b.date));
58	  return call<YextEntity>("PUT", entityId, { hours });
59	}
