61	/** Makes the shared sandbox entity mirror a business (name, city, regular weekly hours) and clears exceptions, so one sandbox entity can show many demo businesses. */
62	export async function mirrorBusiness(entityId: string, b: { name: string; regular: Record<string, string> | null }) {
63	  const day = (h: string | undefined): YextDay => (!h || h === "closed" ? { isClosed: true } : { openIntervals: h.split(",").map((x) => { const [start, end] = x.split("-"); return { start, end }; }) });
64	  const hours: YextHours = { holidayHours: [] };
65	  for (const d of DAYS) (hours as Record<string, YextDay>)[d] = day(b.regular?.[d]);
66	  return call<YextEntity>("PUT", entityId, { name: b.name, hours });
67	}
