69	/** Sets several exceptions at once (e.g. a temporary closure over many days) in one write. Returns what was there before so it can be undone. */
70	export async function setHolidayPlans(entityId: string, items: { date: string; plan: DayPlan }[]): Promise<{ before: YextHoliday[]; after: YextEntity }> {
71	  const current = await getEntity(entityId);
72	  const hours: YextHours = { ...(current.hours ?? {}) };
73	  const dates = new Set(items.map((i) => i.date));
74	  const before = (hours.holidayHours ?? []).filter((x) => dates.has(x.date));
75	  hours.holidayHours = [...(hours.holidayHours ?? []).filter((x) => !dates.has(x.date)), ...items.map((i) => toYext(i.date, i.plan))].sort((a, b) => a.date.localeCompare(b.date));
76	  return { before, after: await call<YextEntity>("PUT", entityId, { hours }) };
77	}
