79	/** Replaces regular weekly hours for the given weekdays only, keeping every other day and all exceptions. */
80	export async function setRegularDays(entityId: string, days: Partial<Record<(typeof DAYS)[number], DayPlan>>): Promise<{ before: Partial<Record<string, YextDay | null>>; after: YextEntity }> {
81	  const current = await getEntity(entityId);
82	  const hours: YextHours = { ...(current.hours ?? {}) };
83	  const before: Partial<Record<string, YextDay | null>> = {};
84	  for (const [d, p] of Object.entries(days) as [(typeof DAYS)[number], DayPlan][]) {
85	    before[d] = hours[d] ?? null;
86	    hours[d] = p.closed ? { isClosed: true } : { openIntervals: p.intervals.map((i) => ({ start: i.start, end: i.end })) };
87	  }
88	  return { before, after: await call<YextEntity>("PUT", entityId, { hours }) };
89	}
