91	/** Writes simple profile fields (phone, website, e-mail, description, address). Returns the previous values for undo. */
92	export async function setProfileFields(entityId: string, fields: Partial<Pick<YextEntity, "mainPhone" | "websiteUrl" | "emails" | "description" | "address">>) {
93	  const current = await getEntity(entityId);
94	  const before = Object.fromEntries(Object.keys(fields).map((k) => [k, (current as unknown as Record<string, unknown>)[k] ?? null]));
95	  return { before, after: await call<YextEntity>("PUT", entityId, fields) };
96	}
97	
98	export async function restoreHolidayEntries(entityId: string, dates: string[], before: YextHoliday[]) {
99	  const current = await getEntity(entityId);
100	  const hours: YextHours = { ...(current.hours ?? {}) };
101	  const drop = new Set(dates);
102	  hours.holidayHours = [...(hours.holidayHours ?? []).filter((x) => !drop.has(x.date)), ...before].sort((a, b) => a.date.localeCompare(b.date));
103	  return call<YextEntity>("PUT", entityId, { hours });
104	}
105	
106	export async function restoreRegularDays(entityId: string, before: Partial<Record<string, YextDay | null>>) {
107	  const current = await getEntity(entityId);
108	  const hours = { ...(current.hours ?? {}) } as Record<string, unknown>;
109	  for (const [d, v] of Object.entries(before)) { if (v) hours[d] = v; else delete hours[d]; }
110	  return call<YextEntity>("PUT", entityId, { hours });
111	}
