7	export const hasWhatsapp = () => !!(process.env.VONAGE_API_KEY && process.env.VONAGE_API_SECRET && process.env.DEMO_PHONE);
8	export const waFrom = () => (process.env.VONAGE_WA_FROM ?? "14157386102").replace(/\D/g, "");
