11	export async function sendWhatsapp(to: string, text: string): Promise<string> {
12	  const res = await fetch(process.env.VONAGE_MESSAGES_URL ?? SANDBOX, {
13	    method: "POST",
14	    headers: { authorization: `Basic ${Buffer.from(`${process.env.VONAGE_API_KEY}:${process.env.VONAGE_API_SECRET}`).toString("base64")}`, "content-type": "application/json", accept: "application/json" },
15	    body: JSON.stringify({ from: waFrom(), to: to.replace(/\D/g, ""), channel: "whatsapp", message_type: "text", text: text.slice(0, 3800) }), signal: AbortSignal.timeout(10_000),
16	  });
17	  const j = (await res.json().catch(() => ({}))) as { message_uuid?: string; title?: string; detail?: string };
18	  if (!res.ok) throw new Error(`WhatsApp: ${j.title ?? res.status}${j.detail ? ` (${j.detail})` : ""}`);
