25	/** Re-draws the original message so decided days drop out of the keyboard and adjusted days show their new hours. */
26	async function refresh(db: DB, biz: Biz, chatId: string, messageId: number, sug: { messageId: string | null }) {
27	  if (!sug.messageId) return;
28	  const msg = await db.select().from(schema.cnMessages).where(eq(schema.cnMessages.id, sug.messageId)).get();
29	  if (!msg) return;
30	  const all = (await sugsFor(db, biz.id)).filter((s) => s.messageId === msg.id);
31	  const b = bundleOf(biz, all, `${process.env.APP_URL ?? ""}/d/${msg.token}`);
32	  const pending = new Set(all.filter((s) => s.status === "sent").map((s) => s.id));
33	  await tg("editMessageText", { chat_id: chatId, message_id: messageId, text: telegramText(b), parse_mode: "HTML", disable_web_page_preview: true, reply_markup: keyboard(b, b.lang, pending, msg.id) }).catch(() => undefined);
34	}
