36	async function after(db: DB, biz: Biz, chatId: string, r: DecideResult, origMsgId?: number) {
37	  const l = asLang(biz.language), t = T[l];
38	  if (!r.ok) { await say(chatId, esc(r.text)); return; }
39	  const undo = r.suggestion && ["applied", "auto_applied"].includes(r.suggestion.status) ? { reply_markup: { inline_keyboard: [[{ text: `↩️ ${t.undo}`, callback_data: `u:${r.suggestion.id}` }]] } } : {};
40	  await say(chatId, r.suggestion?.status === "declined" || r.suggestion?.status === "kept" ? esc(r.text) : confirmText(r, biz), undo);
41	  if (r.adjusted?.length) await say(chatId, `🔁 ${r.adjusted.map((a) => `${esc(a.date)}: ${esc(a.proposed ?? "")}`).join(", ")}\n<i>${esc(t.adjusted(r.suggestion!.date))}</i>`);
42	  if (origMsgId && r.suggestion) await refresh(db, biz, chatId, origMsgId, r.suggestion);
43	}
