45	/** Sends the agent's answer with one Apply / Cancel row per proposed change, and as a voice note when the owner spoke (or prefers voice). */
46	async function sendAgentReply(db: DB, biz: Biz, chatId: string, r: AgentReply) {
47	  const t = { en: ["Apply", "Apply all"], fi: ["Ota käyttöön", "Ota kaikki käyttöön"], sv: ["Tillämpa", "Tillämpa alla"], nb: ["Bruk", "Bruk alle"] }[asLang(biz.language)];
48	  const rows = r.changes.map((c) => [{ text: `✅ ${t[0]}: ${c.label.slice(0, 38)}`, callback_data: `ap:${c.id}` }, { text: "✖️", callback_data: `ax:${c.id}` }]);
49	  if (r.changes.length > 1) rows.push([{ text: `✅ ${t[1]} (${r.changes.length})`, callback_data: `aA:${r.changes[0].id}` }]);
50	  await say(chatId, esc(r.text), rows.length ? { reply_markup: { inline_keyboard: rows } } : {});
51	  if (r.speak && hasVoice()) { const a = await speak(r.text.replace(/[•✅]/g, "")); if (a) await sendVoice(chatId, a).catch(() => undefined); }
52	  if (r.presence) await enqueueAgentJob(db, { type: "presence", businessId: biz.id, chatId, voice: r.speak });
