60	const mimeOf = (path: string) => (/\.png$/i.test(path) ? "image/png" : /\.webp$/i.test(path) ? "image/webp" : "image/jpeg");
61	
62	export async function handleUpdate(db: DB, u: Update) {
63	  const m = u.message;
64	  if (m && (m.photo?.length || m.voice || m.audio)) {
65	    const chatId = String(m.chat.id), biz = await bizByChat(db, chatId);
66	    if (!biz) { await say(chatId, "Open the link from your Connect invitation first."); return; }
67	    if (m.photo?.length) {
68	      const f = await fileBytes(m.photo[m.photo.length - 1].file_id);
69	      if (!f) { await say(chatId, "I couldn't open that photo. Please send it again."); return; }
70	      await ownerInput(db, biz, chatId, { text: m.caption, image: { mime: mimeOf(f.path), b64: Buffer.from(f.bytes).toString("base64") }, source: "photo" });
71	    } else {
72	      const f = await fileBytes((m.voice ?? m.audio)!.file_id), tr = f ? await transcribe(f.bytes) : null;
73	      if (!tr) { await say(chatId, "I couldn't hear that clearly. Could you say it again, or type it?"); return; }
74	      await say(chatId, `🎤 <i>${esc(tr.text)}</i>`);
75	      await ownerInput(db, biz, chatId, { text: tr.text, source: "voice" });
76	    }
77	    return;
78	  }
79	  if (u.message?.text !== undefined) {
80	    const chatId = String(u.message.chat.id), text = u.message.text.trim();
81	    const start = text.match(/^\/start(?:\s+(\S+))?/);
82	    if (start) {
83	      if (!start[1]) { await say(chatId, "Hi! Open the link from your Connect invitation to link this chat to your business."); return; }
84	      const biz = await db.select().from(schema.cnBusinesses).where(eq(schema.cnBusinesses.linkCode, start[1])).get();
85	      if (!biz) { await say(chatId, "That link is not valid any more."); return; }
86	      await db.update(schema.cnBusinesses).set({ telegramChatId: chatId }).where(eq(schema.cnBusinesses.id, biz.id)).run();
87	      await say(chatId, `🔗 ${esc(T[asLang(biz.language)].linked(biz.name))}`);
88	      return;
89	    }
90	    const biz = await bizByChat(db, chatId);
91	    if (!biz) { await say(chatId, "Open the link from your Connect invitation first."); return; }
92	    if (/^\/voice/.test(text)) { const on = !biz.voice; await db.update(schema.cnBusinesses).set({ voice: on ? 1 : 0 }).where(eq(schema.cnBusinesses.id, biz.id)).run(); await say(chatId, on ? "🔊 Voice replies on (AI voice)." : "🔇 Voice replies off."); return; }
93	    if (/^\/(issues|radar)/.test(text)) { await say(chatId, esc(radarText(await computeIssues(db, biz), biz.language))); return; }
94	    if (/^\/(status|presence)/.test(text)) { await ownerInput(db, biz, chatId, { text: "How is my online presence?", source: "text" }); return; }
95	    if (/^\/audit\s+\S+/.test(text)) { await ownerInput(db, biz, chatId, { text: `Audit the website ${text.replace(/^\/audit\s+/, "")}`, source: "text" }); return; }
96	    if (/^\/(suggest|send)/.test(text)) { const r = await sendNow(db, biz.id); if (r.ok && !r.sent) await say(chatId, "No new suggestions right now."); return; }
97	    const sid = await popAwaiting(db, biz.id);
98	    if (!sid) { await ownerInput(db, biz, chatId, { text, source: "text" }); return; }
99	    const r = await decide(db, sid, { action: "edit", text });
100	    if (r.needsRetry) { await setAwaiting(db, biz.id, sid); await say(chatId, esc(r.text)); return; }
101	    await after(db, biz, chatId, r);
102	    if (r.suggestion?.messageId) {
103	      const msg = await db.select().from(schema.cnMessages).where(eq(schema.cnMessages.id, r.suggestion.messageId)).get();
104	      if (msg?.externalRef) await refresh(db, biz, chatId, Number(msg.externalRef), r.suggestion);
105	    }
106	    return;
107	  }
108	  const cq = u.callback_query;
109	  if (!cq?.data || !cq.message) return;
110	  const chatId = String(cq.message.chat.id), biz = await bizByChat(db, chatId);
111	  if (!biz) { await answer(cq.id); return; }
112	  const [kind, ...rest] = cq.data.split(":"), id = rest.join(":");
113	  await answer(cq.id).catch(() => undefined);
114	  if (kind === "all") {
115	    const sent = (await sugsFor(db, biz.id)).filter((s) => s.messageId === id && s.status === "sent" && !isAsk(s));
116	    let last: DecideResult | undefined;
117	    for (const s of sent) { last = await decide(db, s.id, { action: "approve" }); if (last.ok) await after(db, biz, chatId, last); }
118	    if (last?.suggestion) await refresh(db, biz, chatId, cq.message.message_id, last.suggestion);
119	    return;
120	  }
121	  if (kind === "o") {
122	    const sid = rest.slice(0, -1).join(":"), opt = Number(rest.at(-1)), s = await getSug(db, sid);
123	    if (s && s.businessId === biz.id && Number.isInteger(opt)) await after(db, biz, chatId, await decide(db, s.id, { action: "choose", option: opt }), cq.message.message_id);
124	    return;
125	  }
126	  if (kind === "ap" || kind === "ax" || kind === "aA" || kind === "au") {
127	    const rec = await getChange(db, id);
128	    if (!rec || rec.businessId !== biz.id) return;
129	    const l = asLang(biz.language);
130	    const batch = kind === "aA" ? (await db.select().from(schema.cnChanges).where(eq(schema.cnChanges.businessId, biz.id)).all()).filter((x) => x.status === "proposed" && Math.abs(x.createdAt - rec.createdAt) < 120_000) : [rec];
131	    if (kind === "au") { await say(chatId, esc((await undoChange(db, rec)) ? T[l].undone : T[l].alreadyDone)); return; }
132	    if (kind === "ax") { await db.update(schema.cnChanges).set({ status: "declined" }).where(eq(schema.cnChanges.id, rec.id)).run(); await say(chatId, "✖️"); return; }
133	    for (const c of batch) {
134	      if (c.status !== "proposed") { await say(chatId, esc(T[l].alreadyDone)); continue; }
135	      const r = await applyChange(db, biz, c);
136	      if (!r.ok) { await say(chatId, esc(r.error?.startsWith("rule:") ? r.error.slice(5) : T[l].failed)); continue; }
137	      await say(chatId, `✅ <b>${esc(T[l].savedIn)}</b>\n\n<b>${esc(T[l].whereShows)}</b>\n${shows(biz, l).slice(0, 6).map((x) => `${x.live ? "•" : "◦"} ${esc(x.text)}`).join("\n")}`, { reply_markup: { inline_keyboard: [[{ text: `↩️ ${T[l].undo}`, callback_data: `au:${c.id}` }]] } });
138	    }
139	    return;
140	  }
141	  const s = await getSug(db, id);
142	  if (!s || s.businessId !== biz.id) return;
143	  if (kind === "a") await after(db, biz, chatId, await decide(db, s.id, { action: "approve" }), cq.message.message_id);
144	  else if (kind === "n") await after(db, biz, chatId, await decide(db, s.id, { action: "decline" }), cq.message.message_id);
145	  else if (kind === "e") { await setAwaiting(db, biz.id, s.id); await say(chatId, `✏️ <b>${esc(s.date)}</b>\n${esc(T[asLang(biz.language)].editPrompt)}`, { reply_markup: { force_reply: true } }); }
146	  else if (kind === "u") { const r = await undoSuggestion(db, s); await say(chatId, r.ok ? esc(T[asLang(biz.language)].undone) : esc(T[asLang(biz.language)].alreadyDone)); }
147	}
