20	  async queue(batch: MessageBatch<ScanJob>, env: CfEnv) {
21	    const db = dbFromEnv(env);
22	    for (const m of batch.messages) {
23	      const { locationId, scanId, paceMs, trigger, kind, auditId, assistantId, payload } = m.body;
24	      try {
25	        if (kind === "agent" && payload) {
26	          await runAgentJob(db, payload as never);
27	          m.ack();
28	          continue;
29	        }
30	        if (kind === "public_sources" && auditId) {
31	          await runPublicSources(db, auditId);
32	          m.ack();
33	          continue;
34	        }
35	        if (kind === "ai_audit" && auditId && assistantId) {
36	          await runAssistantJob(db, auditId, assistantId);
37	          m.ack();
38	          continue;
39	        }
40	        await executeScan(db, locationId, scanId, { paceMs, trigger: trigger as "manual" | "scheduled" });
41	        m.ack();
42	      } catch {
43	        m.retry();
44	      }
45	    }
46	  },
47	};
